@@ -18,6 +18,58 @@ pub fn monthly_totals(ledger: &Ledger, prefix: &str) -> Vec<(String, Amount)> {
     months.into_iter().collect()
 }

+/// Account balances rolled up to the first `depth` segments of their names, sorted by name,
+/// with zero roll-ups left out. Panics if `depth` is 0.
+pub fn category_totals(ledger: &Ledger, depth: usize) -> Vec<(String, Amount)> {
+    assert!(depth > 0, "depth must be at least 1");
+    let mut totals: BTreeMap<String, Amount> = BTreeMap::new();
+    for tx in ledger.transactions() {
+        for p in &tx.postings {
+            let key: Vec<&str> = p.account.split(':').take(depth).collect();
+            *totals.entry(key.join(":")).or_default() += p.amount;
+        }
+    }
+    totals.into_iter().filter(|(_, a)| *a != Amount::ZERO).collect()
+}
+
+#[cfg(test)]
+mod category_tests {
+    use super::*;
+    use ledger_core::Transaction;
+
+    #[test]
+    fn category_totals_roll_up_and_drop_zeros() {
+        let mut l = Ledger::new();
+        l.record(Transaction::new("2026-01-02", "groceries").post("expenses:food:groceries", Amount::from_cents(6250)).post("expenses:food:dining", Amount::from_cents(420)).post("assets:bank", Amount::from_cents(-6670))).unwrap();
+        l.record(Transaction::new("2026-01-03", "transfer").post("assets:bank", Amount::from_cents(500)).post("assets:cash", Amount::from_cents(-500))).unwrap();
+        l.record(Transaction::new("2026-01-04", "misc").post("expenses:misc:a", Amount::from_cents(300)).post("expenses:misc:b", Amount::from_cents(-300))).unwrap();
+        l.record(Transaction::new("2026-01-05", "cash").post("cash", Amount::from_cents(100)).post("assets:bank", Amount::from_cents(-100))).unwrap();
+        assert_eq!(
+            category_totals(&l, 2),
+            vec![
+                ("assets:bank".to_string(), Amount::from_cents(-6270)),
+                ("assets:cash".to_string(), Amount::from_cents(-500)),
+                ("cash".to_string(), Amount::from_cents(100)),
+                ("expenses:food".to_string(), Amount::from_cents(6670)),
+            ]
+        );
+        assert_eq!(
+            category_totals(&l, 1),
+            vec![
+                ("assets".to_string(), Amount::from_cents(-6770)),
+                ("cash".to_string(), Amount::from_cents(100)),
+                ("expenses".to_string(), Amount::from_cents(6670)),
+            ]
+        );
+    }
+
+    #[test]
+    #[should_panic]
+    fn category_totals_rejects_zero_depth() {
+        category_totals(&Ledger::new(), 0);
+    }
+}
