+    let mut totals: BTreeMap<String, Amount> = BTreeMap::new();
+    for (account, amount) in ledger.balances() {
+        let parts: Vec<&str> = account.split(':').collect();
+        let key = if parts.len() > depth { parts[..depth].join(":") } else { account.to_string() };
+        *totals.entry(key).or_default() += amount;
+    }
+    totals.into_iter().filter(|(_, a)| *a != Amount::ZERO).collect()
+}
+
