+mod tests {
+    use super::category_totals;
+    use ledger_core::{Amount, Ledger, Transaction};
+
+    #[test]
+    fn category_totals_roll_up_and_skip_zero() {
+        let mut ledger = Ledger::new();
+        ledger.record(Transaction::new("2024-01-05", "groceries").post("expenses:food:groceries", Amount::from_cents(1000)).post("assets:bank", Amount::from_cents(-1000))).unwrap();
+        ledger.record(Transaction::new("2024-01-06", "cafe").post("expenses:food:cafe", Amount::from_cents(500)).post("expenses:rent", Amount::from_cents(-500))).unwrap();
+        ledger.record(Transaction::new("2024-01-07", "move").post("assets:cash:a", Amount::from_cents(300)).post("assets:cash:b", Amount::from_cents(-300))).unwrap();
+        let totals = category_totals(&ledger, 2);
+        assert_eq!(totals, vec![
+            ("assets:bank".to_string(), Amount::from_cents(-1000)),
+            ("expenses:food".to_string(), Amount::from_cents(1500)),
+            ("expenses:rent".to_string(), Amount::from_cents(-500)),
+        ]);
+    }
+
+    #[test]
+    #[should_panic]
+    fn category_totals_rejects_zero_depth() {
+        category_totals(&Ledger::new(), 0);
+    }
+}

